import{c as t,Q as e,j as s,m as r}from"./chunks/framework.CHJbb1iY.js";const o="/my-knowledge/assets/38%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%9B%BE%E4%BE%8B.CShN5zwM.png",l="/my-knowledge/assets/68%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%9B%BE%E4%BE%8B.BeLZyjmr.png",p="/my-knowledge/assets/%E6%97%A0%E5%A4%87%E6%A1%88%E6%97%A0%E6%B3%95%E8%AE%BF%E9%97%AE.ChdT3s9s.png",i="/my-knowledge/assets/%E9%87%8D%E8%A3%85%E7%B3%BB%E7%BB%9F1.eC1p8z4D.png",n="/my-knowledge/assets/%E9%87%8D%E8%A3%85%E7%B3%BB%E7%BB%9F2.DD9BKg_i.png",A="/my-knowledge/assets/%E5%AE%9D%E5%A1%94%E9%9D%A2%E6%9D%BF%E7%AB%AF%E5%8F%A3.KRx24cmW.png",h="/my-knowledge/assets/%E9%98%B2%E7%81%AB%E5%A2%99%E7%95%8C%E9%9D%A2.XTEJGkOB.png",g="/my-knowledge/assets/%E6%B7%BB%E5%8A%A0888%E7%AB%AF%E5%8F%A3.D2TKvmei.png",d="/my-knowledge/assets/%E5%AE%9D%E5%A1%94%E9%9D%A2%E6%9D%BF%E8%BD%AF%E4%BB%B6%E5%AE%89%E8%A3%85.D5DDv0mh.png",E="/my-knowledge/assets/%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90%E8%AE%B0%E5%BD%95%E7%95%8C%E9%9D%A2.DA45Pqgq.png",c="data:image/png;base64,",m="/my-knowledge/assets/%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.Cld2WXT8.png",u="/my-knowledge/assets/base%E7%9A%84%E9%85%8D%E7%BD%AE%E9%97%AE%E9%A2%98.pp3M7Ygs.png",b="/my-knowledge/assets/%E5%AE%9D%E5%A1%94%E6%B7%BB%E5%8A%A0%E7%BD%91%E7%AB%99%E9%A1%B9%E7%9B%AE.C8H3q9SB.png",C="/my-knowledge/assets/%E4%B8%8A%E4%BC%A0%E7%BD%91%E9%A1%B5%E6%96%87%E4%BB%B6.DDiXsT_R.png",k="/my-knowledge/assets/%E7%94%B3%E8%AF%B7SSL%E8%AF%81%E4%B9%A6.BZIqQypi.png",B="/my-knowledge/assets/%E8%87%AA%E5%8A%A8DNS%E9%AA%8C%E8%AF%81.bR0HD0ZO.png",Q="/my-knowledge/assets/%E4%B8%8B%E8%BD%BDSSL%E8%AF%81%E4%B9%A6.CqNUV5AY.png",I="data:image/png;base64,",f="/my-knowledge/assets/%E7%82%B9%E5%87%BBssl%E8%AF%81%E4%B9%A6%E9%83%A8%E7%BD%B2.BqUTGbL7.png",D="/my-knowledge/assets/%E6%B7%BB%E5%8A%A0ssl%E8%AF%81%E4%B9%A6.DgYVmopv.png",q="/my-knowledge/assets/%E5%BC%BA%E5%88%B6%E5%BC%80%E5%90%AFhttps.Cy-BUKpR.png",S="/my-knowledge/assets/%E5%AE%9D%E5%A1%94%E5%8A%9F%E8%83%BD%E9%9D%A2%E6%9D%BF.DiYVPDgx.png",F=JSON.parse('{"title":"","description":"","frontmatter":{"sidebar":false,"aside":"left","outline":[2,4]},"headers":[],"relativePath":"docs/笔记/vitepress教程/腾讯云部署/腾讯云部署.md","filePath":"docs/笔记/vitepress教程/腾讯云部署/腾讯云部署.md"}'),v={name:"docs/笔记/vitepress教程/腾讯云部署/腾讯云部署.md"};function y(R,a,x,L,j,z){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 style="text-align:center;">腾讯云部署教程</h1><hr><h2 id="_1-准备工作" tabindex="-1">1. 准备工作 <a class="header-anchor" href="#_1-准备工作" aria-label="Permalink to &quot;1. 准备工作&quot;">​</a></h2><p>腾讯云官网：<a href="https://cloud.tencent.com/" target="_blank" rel="noreferrer">https://cloud.tencent.com/</a></p><p>说明：本教程的服务器和域名均采用腾讯云的产品</p><h3 id="_1-个人账号完善" tabindex="-1">(1) 个人账号完善 <a class="header-anchor" href="#_1-个人账号完善" aria-label="Permalink to &quot;(1) 个人账号完善&quot;">​</a></h3><ol><li><p>在官网完成个人账号的注册和实名认证</p></li><li><p>若需购买域名需要创建好个人信息模板</p></li><li><p>如果是学生，可以完成学生认证，购买更优惠（<a href="https://cloud.tencent.com/act/campus?from=19070" target="_blank" rel="noreferrer">点我跳转学生优惠活动专区</a>）</p></li></ol><h3 id="_2-购买服务器" tabindex="-1">(2) 购买服务器 <a class="header-anchor" href="#_2-购买服务器" aria-label="Permalink to &quot;(2) 购买服务器&quot;">​</a></h3><h4 id="_1-购买介绍" tabindex="-1">1. 购买介绍 <a class="header-anchor" href="#_1-购买介绍" aria-label="Permalink to &quot;1. 购买介绍&quot;">​</a></h4><p>618 特惠服务器：38 / 年（<a href="https://cloud.tencent.com/act/pro/warmup202506?from=27490" target="_blank" rel="noreferrer">点我跳转 618 特惠活动</a>）</p><p><img src="'+o+'" alt="alt text"></p><p>如果是新用户，可以享受一次优惠，建议如果价格在能承受的范围内，一次购买的时间越长越好，后续续费会越来越贵，由于上面的活动太抢手了，jacksonling 购买的是新用户优惠活动的服务器</p><p><img src="'+l+'" alt="alt text"></p><h4 id="_2-购买说明" tabindex="-1">2. 购买说明 <a class="header-anchor" href="#_2-购买说明" aria-label="Permalink to &quot;2. 购买说明&quot;">​</a></h4><p>服务器配置参数解释：</p><p>cpu: 1 核 1G 就够用了。</p><p>带宽：带宽越大，打开网页、从服务器下载东西的速度越快</p><p>系统盘：够用就好，一般静态资源、数据库、缓存都是存到其他地方去</p><p>月流量：这个够用就好，300G 小公司网站都用不完</p><p>时长：优惠购买只能一次，能承受范围内，时长越长越好，配置越高越好。</p><h3 id="_3-购买域名" tabindex="-1">(3) 购买域名 <a class="header-anchor" href="#_3-购买域名" aria-label="Permalink to &quot;(3) 购买域名&quot;">​</a></h3><p><a href="https://cloud.tencent.com/product/domain" target="_blank" rel="noreferrer">点我跳转腾讯云域名注册</a></p><p>购买说明</p><ul><li>域名可以根据自己的喜好进行挑选，不同的域名价格也不相同</li><li>域名一次最多购买十年，如果需要长期使用，在能力承受范围内建议一次性购买时间为 3 / 5 年</li><li>域名购买后需要备案才可以使用，通过 DNS 解析来和服务器匹配，最终通过域名来访问网站 (<a href="https://cloud.tencent.com/product/ba" target="_blank" rel="noreferrer">点我跳转腾讯云域名备案</a>)，<strong>根据步骤提示完成备案流程即可</strong></li></ul><p><strong>注意点：域名如果没有备案成功，是无法通过购买的域名访问对应的网址的</strong>，这个时候可以暂时用服务器的 ip 地址代替域名访问网站 <img src="'+p+'" alt="alt text"></p><hr><h2 id="_2-部署方法" tabindex="-1">2. 部署方法 <a class="header-anchor" href="#_2-部署方法" aria-label="Permalink to &quot;2. 部署方法&quot;">​</a></h2><h3 id="_1-说明" tabindex="-1">(1) 说明 <a class="header-anchor" href="#_1-说明" aria-label="Permalink to &quot;(1) 说明&quot;">​</a></h3><p>服务器使用的是<strong>宝塔面板</strong>，如果不是可以选择<strong>重装系统</strong></p><p><img src="'+i+'" alt="alt text"></p><p><img src="'+n+'" alt="alt text"></p><h3 id="_2-预备工作" tabindex="-1">(2) 预备工作 <a class="header-anchor" href="#_2-预备工作" aria-label="Permalink to &quot;(2) 预备工作&quot;">​</a></h3><p><strong>开放 8888 端口</strong></p><ol><li>进入控制台</li><li>进入服务器管理界面</li><li>进入应用管理界面，找到应用内软件信息</li></ol><p><img src="'+A+'" alt="alt text"></p><ol start="4"><li><p>点击防火墙</p></li><li><p>点击添加规则，开放 8888 端口</p></li><li><p><strong>点击添加规则</strong></p></li></ol><p><img src="'+h+'" alt="alt text"></p><ol start="7"><li><strong>添加端口</strong></li></ol><p><img src="'+g+'" alt="alt text"></p><h3 id="_3-部署步骤" tabindex="-1">(3) 部署步骤 <a class="header-anchor" href="#_3-部署步骤" aria-label="Permalink to &quot;(3) 部署步骤&quot;">​</a></h3><h4 id="_1-初始化宝塔面板" tabindex="-1">1. 初始化宝塔面板 <a class="header-anchor" href="#_1-初始化宝塔面板" aria-label="Permalink to &quot;1. 初始化宝塔面板&quot;">​</a></h4><ol><li>进入控制台中，进入个人服务器的应用管理界面，<strong>使用提供的命令初始化宝塔面板</strong>，此时会生成默认的账号和密码，复制提供的<strong>外网 ipv4 面板地址</strong>到浏览器中，使用默认的账号密码登录</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> /etc/init.d/bt</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> default</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>首次进入会提示安装如下内容 <img src="'+d+'" alt="alt text"></li><li>进入左边栏的设置界面，重置一下用户名和密码</li></ol><h4 id="_2-域名解析" tabindex="-1">2. 域名解析 <a class="header-anchor" href="#_2-域名解析" aria-label="Permalink to &quot;2. 域名解析&quot;">​</a></h4><p>点击控制台，找到个人域名，点击解析，跳转界面后点击<strong>添加记录</strong></p><p><img src="'+E+'" alt="alt text"></p><p>添加两条记录，记录值填写自己服务器的 IP 地址即可</p><p><img src="'+c+'" alt="alt text"></p><p>回到服务器管理界面，点击添加域名解析，把刚刚的解析记录添加进来</p><p><img src="'+m+'" alt="alt text"></p><h4 id="_3-上传网页文件" tabindex="-1">3. 上传网页文件 <a class="header-anchor" href="#_3-上传网页文件" aria-label="Permalink to &quot;3. 上传网页文件&quot;">​</a></h4><p><strong>准备工作</strong></p><p>由于本站初次部署是在 <strong>Github</strong> 上完成的，这里会在 config.mjs 文件中<strong>配置 base</strong>，<strong style="color:red;">如果使用国内的服务器，则不需要配置 base</strong>，具体原因如下</p><p><img src="'+u+'" alt="alt text"></p><p>（1）在宝塔面板左侧选择网站，添加对应的项目类型（本站选择是 html）</p><p><img src="'+b+'" alt="alt text"></p><p>（2）点击<strong>根目录</strong>，跳转到文件界面，上传网站文件即可</p><p><strong>注意</strong>：上传之前需要将网站文件打包（<code>pnpm run docs:build</code>），把 <strong>dist 文件夹中的所有文件</strong>（可以通过全选 + 拖拽的方法上传）上传，而且必须在项目的<strong>根目录</strong></p><p><img src="'+C+'" alt="alt text"></p><h4 id="_4-申请-ssl-证书" tabindex="-1">4. 申请 SSL 证书 <a class="header-anchor" href="#_4-申请-ssl-证书" aria-label="Permalink to &quot;4. 申请 SSL 证书&quot;">​</a></h4><p><strong>（1）在控制台中搜索 SSL 证书，点击申请免费的证书</strong></p><p><img src="'+k+'" alt="alt text"></p><p><strong>（2）选择自动 DNS 认证</strong></p><p><img src="'+B+'" alt="alt text"></p><p><strong>（3）证书签发成功后，点击下载 Nginx 版本文件</strong></p><p><img src="'+Q+'" alt="alt text"></p><p>证书内容如下</p><p><img src="'+I+'" alt="alt text"></p><p><strong>（4）回到宝塔面板配置证书</strong></p><ol><li>点击部署</li></ol><p><img src="'+f+'" alt="alt text"></p><ol start="2"><li>根据提示，粘贴对应文件的内容，保存</li></ol><p><img src="'+D+'" alt="alt text"></p><ol start="3"><li><strong>证书添加成功后，强制开启 https</strong></li></ol><p><img src="'+q+'" alt="alt text"></p><h2 id="_3-内容补充" tabindex="-1">3. 内容补充 <a class="header-anchor" href="#_3-内容补充" aria-label="Permalink to &quot;3. 内容补充&quot;">​</a></h2><h3 id="_1-网站内容更新" tabindex="-1">1. 网站内容更新 <a class="header-anchor" href="#_1-网站内容更新" aria-label="Permalink to &quot;1. 网站内容更新&quot;">​</a></h3><p>登录服务器，使用如下命令启动宝塔</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">bt</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>启动服务后，根据初始化时宝塔给的外网 ipv4 面板地址来访问宝塔面板，上传新的网站文件即可</p><p>完成操作后使用如下命令关闭服务</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">bt</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> stop</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h5 id="注意-需要在-cdn-配置界面-手动刷新-cdn-缓存-否则网站内容无法更新" tabindex="-1">注意：需要在 CDN 配置界面，<span style="color:red;font-size:20px;">手动刷新 CDN 缓存</span>，否则网站内容无法更新 <a class="header-anchor" href="#注意-需要在-cdn-配置界面-手动刷新-cdn-缓存-否则网站内容无法更新" aria-label="Permalink to &quot;注意：需要在 CDN 配置界面，&lt;span style=&quot;color:red;font-size:20px&quot;&gt;手动刷新 CDN 缓存&lt;/span&gt;，否则网站内容无法更新&quot;">​</a></h5><h3 id="_2-更多宝塔功能" tabindex="-1">2. 更多宝塔功能 <a class="header-anchor" href="#_2-更多宝塔功能" aria-label="Permalink to &quot;2. 更多宝塔功能&quot;">​</a></h3><p>登录服务器，输入如下命令，之后根据提示选择对应的功能</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">bt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+S+'" alt="alt text"></p><h3 id="_3-ssl-证书过期-重新申请" tabindex="-1">3. SSL 证书过期，重新申请 <a class="header-anchor" href="#_3-ssl-证书过期-重新申请" aria-label="Permalink to &quot;3. SSL 证书过期，重新申请&quot;">​</a></h3><p>在控制台搜索 SSL 证书，再次申请一张并在宝塔界面从新配置即可，方法和前面相同</p><h3 id="_4-cdn-加速配置方法" tabindex="-1">4. CDN 加速配置方法 <a class="header-anchor" href="#_4-cdn-加速配置方法" aria-label="Permalink to &quot;4. CDN 加速配置方法&quot;">​</a></h3><h3 id="_5-⚠️-图片资源" tabindex="-1">5. ⚠️ 图片资源 <a class="header-anchor" href="#_5-⚠️-图片资源" aria-label="Permalink to &quot;5. ⚠️ 图片资源&quot;">​</a></h3><p>vitepress 模式下会自动映射 public 目录下的图片路径，只需要写图片的名称，<span style="color:red;font-weight:bold;font-size:20px;">图片路径不用写/public/..，确保该目录在根目录下</span></p>',93)])])}const H=t(v,[["render",y]]);export{F as __pageData,H as default};
